import re

from taf.ul.trs_e2e_fw.lib.remote_connection.controller import Controller
from taf.ul.trs_e2e_fw.lib.remote_connection.remoteconnection import RemoteConnection
from taf.ul.trs_e2e_fw.lib.utils.front_haul_modules.exceptions import IPAddressNotFound
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class BaseBandModule:
    def __init__(self):
        self.remote_conn = RemoteConnection()
        self.controller = Controller()

    def bbmodule_setup(self, **kwargs):
        config_device = kwargs.get("config_device", "bts")
        timeout = kwargs.pop("timeout", 10)
        alias = kwargs.pop("alias", "default")
        fsp_id = kwargs.pop("fsp_id", "fsp-1b")
        host_details = self.remote_conn.get_host_details(config_device)
        host_details.update(kwargs)
        logger.info("Host Details are  {0}".format(host_details))
        self._login_to_bb_module(host_details, fsp_id, timeout, alias)

    def bbmodule_teardown(self, **kwargs):
        alias = kwargs.pop("alias", 'default')
        self.controller.close_session_with_host(alias)

    def _login_to_bb_module(self, host_details, fsp_id, timeout, alias):
        self.controller.create_session_with_host(host_details, alias, timeout)
        fsp_ip_addr = self._fetch_fsp_ip_address(fsp_id, alias)
        logger.debug("response {}".format(fsp_ip_addr))
        ssh_command = "ssh {0}@{1}".format(host_details["user"], fsp_ip_addr)
        logger.debug("connect to bb module {}".format(ssh_command))
        prompt = host_details["prompt"] if host_details["prompt"] else '>'
        self.controller.connect_to_hop(command=ssh_command, alias=alias, password=host_details["password"],
                                       prompt=prompt)
        logger.debug("login to Baseband was successful")

    def _fetch_fsp_ip_address(self, fsp_id, alias):
        resp = self.controller.execute_command_on_shell("cat /etc/hosts | grep {}".format(fsp_id), alias)
        try:
            ipv6_address = re.search('(([0-9a-f]{1,4}:){1,4}(:[0-9a-f]{1,4}){1,6})', resp).groups()
        except AttributeError as e:
            raise IPAddressNotFound("IPv6 address not found for give fsp id {}"
                                    ":{}".format(fsp_id, e))
        return ipv6_address[0]
